"""Special quasirandom structures, generated by icet.

This module only adapts icet: it builds the parent lattice from a
:class:`~discopt.calphad.mlip.prototypes.PhaseStructure`, asks icet's
``generate_sqs`` for a structure at an exact composition, and caches the
result. icet is an optional dependency (``pip install discopt-calphad[sqs]``).
"""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np

from discopt.calphad.mlip.calculator import RelaxationCache, structure_hash

__all__ = ["SQSOptions", "sqs_sizes", "generate"]


@dataclass(frozen=True)
class SQSOptions:
    """Settings for SQS generation.

    ``count`` structures are made per composition, in the smallest supercells
    (between ``min_atoms`` and ``max_atoms`` atoms) that hold the composition
    exactly; their spread is the default σ. ``cutoffs`` are the pair, triplet,
    ... cluster cutoffs as multiples of the nearest-neighbour distance.
    ``n_steps`` is the length of icet's simulated annealing (None: icet's default).
    """

    count: int = 2
    min_atoms: int = 8
    max_atoms: int = 32
    cutoffs: tuple[float, ...] = (2.1, 1.5)
    n_steps: int | None = None
    seed: int = 0


def _icet():
    try:
        import icet
        from icet.tools.structure_generation import generate_sqs
    except ImportError as err:
        raise ImportError("method='sqs' needs icet: pip install 'discopt-calphad[sqs]' (or pip install icet)") from err
    return icet, generate_sqs


def _template(ps, mixing: int, pair, fixed, volume_per_atom):
    """The parent lattice as Atoms, and icet's per-site allowed species."""
    endmember = [pair[0] if s == mixing else fixed[s] for s in range(len(ps.sublattices))]
    atoms = ps.build(endmember, volume_per_atom)
    sites = set(ps.sublattices[mixing])
    allowed = [
        [pair[0].capitalize(), pair[1].capitalize()] if w in sites else [a]
        for w, a in zip(atoms.get_array("wyckoff"), atoms.get_chemical_symbols())
    ]
    return atoms, allowed


def _cluster_space(atoms, allowed, cutoffs_nn):
    from ase.neighborlist import neighbor_list

    icet, _ = _icet()
    d = neighbor_list("d", atoms, 2.0 * (atoms.get_volume() / len(atoms)) ** (1 / 3))
    cutoffs = [c * float(d.min()) for c in cutoffs_nn]
    return icet.ClusterSpace(atoms, cutoffs=cutoffs, chemical_symbols=allowed), cutoffs


def _active(cs, pair):
    symbols = {p.capitalize() for p in pair}
    for sl in cs.get_sublattices(cs.primitive_structure):
        if set(sl.chemical_symbols) == symbols:
            return sl.symbol, len(sl.indices)
    raise ValueError(f"no sublattice mixes {sorted(symbols)} in the cluster space")


def sqs_sizes(y: float, sites_per_cell: int, atoms_per_cell: int, options: SQSOptions) -> list[int]:
    """Supercell sizes (in primitive cells) that hold site fraction ``y`` exactly, smallest first."""
    out = []
    n = 1
    while n * atoms_per_cell <= options.max_atoms:
        k = y * n * sites_per_cell
        if n * atoms_per_cell >= options.min_atoms and abs(k - round(k)) < 1e-9:
            out.append(n)
        n += 1
    return out


def generate(
    ps,
    mixing: int,
    pair,
    fixed,
    y: float,
    volume_per_atom: float,
    options: SQSOptions,
    cache: RelaxationCache | None = None,
) -> list:
    """``options.count`` SQS for site fraction ``y`` of ``pair[0]`` on sublattice ``mixing``.

    ``fixed`` gives the constituent of every other sublattice (``"VA"`` for an
    empty one). Raises when fewer than ``options.count`` supercell sizes hold
    ``y`` exactly; choose grid points the supercells can represent, or raise
    ``max_atoms``.
    """
    from ase import Atoms

    icet, generate_sqs = _icet()
    template, allowed = _template(ps, mixing, pair, fixed, volume_per_atom)
    cs, cutoffs = _cluster_space(template, allowed, options.cutoffs)
    symbol, sites = _active(cs, pair)
    prim_atoms = len(cs.primitive_structure)
    sizes = sqs_sizes(y, sites, prim_atoms, options)
    if len(sizes) < options.count:
        raise ValueError(
            f"{ps.prototype.name}: only {len(sizes)} supercells of {options.min_atoms}-{options.max_atoms} atoms "
            f"hold y = {y:g} exactly, {options.count} needed; change the composition grid or SQSOptions"
        )
    out = []
    target = {symbol: {pair[0].capitalize(): y, pair[1].capitalize(): 1.0 - y}}
    for i, n in enumerate(sizes[: options.count]):
        key = RelaxationCache.key(
            "sqs", icet.__version__, structure_hash(template), allowed, cutoffs, y, n, options.n_steps, options.seed + i
        )
        hit = cache.get(key) if cache is not None else None
        if hit is None:
            s = generate_sqs(
                cs, n, target, include_smaller_cells=False, n_steps=options.n_steps, random_seed=options.seed + i
            )
            hit = {
                "numbers": s.get_atomic_numbers().tolist(),
                "positions": s.get_positions().tolist(),
                "cell": np.asarray(s.cell).tolist(),
            }
            if cache is not None:
                cache.put(key, hit)
        out.append(Atoms(numbers=hit["numbers"], positions=hit["positions"], cell=hit["cell"], pbc=True))
    return out
